import { createContext, useContext, useEffect, useMemo, useState } from "react";
import { DEFAULT_RANGES, TYPICAL, WAVES, type Params, type Ranges } from "./engine/ecgsyn";
import { DEFAULT_SPACE, type Space } from "./engine/fitting";
import type { BeatClass } from "./engine/rhythm";

export const NOTICE =
  "Synthetic heartbeat generated by SimHeart for research and teaching. Not real patient data and not for clinical use.";

export interface ModelInfo {
  model: string;
  beat_type: string;
  seed: number;
  is_default: boolean;
}

export interface Status {
  ok: boolean;
  bundle: boolean;
  bundle_error: string | null;
  model_dir: string;
  notice: string;
  models: ModelInfo[];
  attribution: string;
  param_space?: Space;
}

export interface BeatsResponse {
  values: number[][];
  time_ms: number[];
  beat_type: string;
  source: "simdcgan" | "dcgan" | "simulator" | "real";
  synthetic: boolean;
  info: Record<string, unknown> & { records?: string[]; seed?: number };
}

async function json<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (!res.ok) {
    let detail = res.statusText;
    try {
      detail = (await res.json()).detail ?? detail;
    } catch {
      /* not JSON */
    }
    throw new Error(`${res.status} · ${detail}`);
  }
  return res.json() as Promise<T>;
}

export const backend = {
  status: () => json<Status>("/api/status"),
  presets: () =>
    json<Record<string, { params: Params; ranges: Ranges }>>("/api/presets"),
  generate: (q: { beat_type: string; n: number; model: string; seed?: number; random_state?: number }) =>
    json<BeatsResponse>(`/api/generate?${qs(q)}`),
  real: (q: { beat_type: string; n: number; random_state?: number }) =>
    json<BeatsResponse>(`/api/real?${qs(q)}`),
  calibrate: (beat: number[], steps = 300) =>
    json<{ params: Params; z0: number; r2: number; fit: BeatsResponse }>("/api/calibrate", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ beat, steps }),
    }),
};

function qs(q: Record<string, string | number | undefined>) {
  const p = new URLSearchParams();
  for (const [k, v] of Object.entries(q)) if (v !== undefined && v !== "") p.set(k, String(v));
  return p.toString();
}

export type Link = "connecting" | "online" | "offline";

export interface TwinContext {
  link: Link;
  status: Status | null;
  /** N always comes from the typical values; S/V/F from the bundle's fitted medians when present. */
  presets: Record<BeatClass, Params>;
  /** Plausible band per slider (1st–99th percentile of fitted values), when the bundle is loaded. */
  bands: Partial<Record<BeatClass, Ranges>>;
  limits: Ranges;
  space: Space;
  presetSource: "bundle" | "typical";
}

const fallback: TwinContext = {
  link: "connecting",
  status: null,
  presets: TYPICAL,
  bands: {},
  limits: DEFAULT_RANGES,
  space: DEFAULT_SPACE,
  presetSource: "typical",
};

export const Twin = createContext<TwinContext>(fallback);
export const useTwin = () => useContext(Twin);

/** Poll the server; keep working offline with the in-browser simulator. */
export function useTwinState(): TwinContext {
  const [link, setLink] = useState<Link>("connecting");
  const [status, setStatus] = useState<Status | null>(null);
  const [remote, setRemote] = useState<Record<string, { params: Params; ranges: Ranges }> | null>(null);

  useEffect(() => {
    let alive = true;
    let hadBundle = false;
    const tick = async () => {
      try {
        const s = await backend.status();
        if (!alive) return;
        setStatus(s);
        setLink("online");
        if (s.bundle && !hadBundle) {
          hadBundle = true;
          setRemote(await backend.presets());
        }
        if (!s.bundle) {
          hadBundle = false;
          setRemote(null);
        }
      } catch {
        if (!alive) return;
        setLink("offline");
        setStatus(null);
        setRemote(null);
        hadBundle = false;
      }
    };
    tick();
    const id = setInterval(tick, 8000);
    return () => {
      alive = false;
      clearInterval(id);
    };
  }, []);

  return useMemo(() => {
    if (!remote) return { ...fallback, link, status };
    const presets = { ...TYPICAL } as Record<BeatClass, Params>;
    const bands: Partial<Record<BeatClass, Ranges>> = {};
    const limits = structuredClone(DEFAULT_RANGES);
    for (const c of ["S", "V", "F"] as const) {
      if (!remote[c]) continue;
      presets[c] = remote[c].params;
      bands[c] = remote[c].ranges;
      for (const w of WAVES)
        for (const f of ["a", "b", "theta_deg"] as const) {
          const [lo, hi] = remote[c].ranges[w][f];
          limits[w][f] = [Math.min(limits[w][f][0], lo), Math.max(limits[w][f][1], hi)];
        }
    }
    return {
      link,
      status,
      presets,
      bands,
      limits,
      space: status?.param_space ?? DEFAULT_SPACE,
      presetSource: "bundle",
    };
  }, [link, status, remote]);
}
